import{_ as s,a0 as r,w as p,s as d,I as l,x as t,a1 as a,A as o,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"netdev 第二天：从网络代码中移除“尽可能快”这个目标 | LCTT x X-CMD","titleTemplate":false,"description":"netdev 第二天：从网络代码中移除“尽可能快”这个目标 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"netdev 第二天：从网络代码中移除“尽可能快”这个目标 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"netdev 第二天：从网络代码中移除“尽可能快”这个目标 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180712 netdev day 2 moving away from as fast as possible in networking code","title":"netdev 第二天：从网络代码中移除“尽可能快”这个目标","tag":"201808","desc":""},"relativePath":"201808/20180712 netdev day 2 moving away from as fast as possible in networking code.md","filePath":"[post].md"}'),u={name:"201808/20180712 netdev day 2 moving away from as fast as possible in networking code.md"};function f(b,n,m,x,T,g){const i=r("Link");return p(),d("div",null,[n[33]||(n[33]=l("h1",{id:"netdev-第二天-从网络代码中移除-尽可能快-这个目标",tabindex:"-1"},[t("netdev 第二天：从网络代码中移除“尽可能快”这个目标 "),l("a",{class:"header-anchor",href:"#netdev-第二天-从网络代码中移除-尽可能快-这个目标","aria-label":"Permalink to “netdev 第二天：从网络代码中移除“尽可能快”这个目标”"},"​")],-1)),l("p",null,[n[1]||(n[1]=t("嗨！今天是 netdev 会议的第 2 天，我只参加了早上的会议，但它_非常有趣_。今早会议的主角是 ",-1)),a(i,{href:"https://en.wikipedia.org/wiki/Van_Jacobson"},{default:o(()=>[...n[0]||(n[0]=[t("Van Jacobson",-1)])]),_:1}),n[2]||(n[2]=t(" 给出的一场名为 “从尽可能快中变化：教网卡以时间”的演讲，它的主题是关于互联网中拥塞控制的未来！！！",-1))]),n[34]||(n[34]=l("p",null,"下面我将尝试着对我从这次演讲中学到的东西做总结，我几乎肯定下面的内容有些错误，但不管怎样，让我们开始吧！",-1)),n[35]||(n[35]=l("p",null,"这次演讲是关于互联网是如何从 1988 开始改变的，为什么现在我们需要新的算法，以及我们可以怎样改变 Linux 的网络栈来更容易地实现这些算法。",-1)),n[36]||(n[36]=l("h3",{id:"什么是拥塞控制",tabindex:"-1"},[t("什么是拥塞控制？ "),l("a",{class:"header-anchor",href:"#什么是拥塞控制","aria-label":"Permalink to “什么是拥塞控制？”"},"​")],-1)),n[37]||(n[37]=l("p",null,"在网络上的任何成员总是无时无刻地发送信息包，而在互联网上的连接之间有着极其不同的速度（某些相比其他极其缓慢），而有时候它们将被塞满！当互联网的一个设备以超过它能处理的速率接收信息包时，它将丢弃某些信息包。",-1)),n[38]||(n[38]=l("p",null,"你所能想象的最天真的发送信息包方式是：",-1)),n[39]||(n[39]=l("ol",null,[l("li",null,"将你必须发送的信息包一次性发送完。"),l("li",null,"假如你发现其中有的信息包被丢弃了，就马上重新发送这些包。")],-1)),l("p",null,[n[4]||(n[4]=t("结果表明假如你按照上面的思路来实现 TCP，互联网将会崩溃并停止运转。我们知道它会崩溃是因为在 1986 年确实发生了崩溃的现象。为了解决这个问题，专家发明了拥塞控制算法 —— 描述如何避免互联网的崩溃的原始论文是 Van Jacobson 于 1988 年发表的 ",-1)),a(i,{href:"https://cs162.eecs.berkeley.edu/static/readings/jacobson-congestion.pdf"},{default:o(()=>[...n[3]||(n[3]=[t("拥塞避免与控制",-1)])]),_:1}),n[5]||(n[5]=t("（30 年前！）。",-1))]),n[40]||(n[40]=l("h3",{id:"从-1988-年后互联网发生了什么改变",tabindex:"-1"},[t("从 1988 年后互联网发生了什么改变？ "),l("a",{class:"header-anchor",href:"#从-1988-年后互联网发生了什么改变","aria-label":"Permalink to “从 1988 年后互联网发生了什么改变？”"},"​")],-1)),n[41]||(n[41]=l("p",null,"在演讲中，Van Jacobson 说互联网的这些已经发生了改变：在以前的互联网上，交换机可能总是拥有比服务器更快的网卡，所以这些位于互联网中间层的服务器也可能比客户端更快，并且并不能对客户端发送信息包的速率有多大影响。",-1)),n[42]||(n[42]=l("p",null,"很显然今天已经不是这样的了！众所周知，今天的计算机相比于 5 年前的计算机在速度上并没有多大的提升（我们遇到了某些有关光速的问题）。所以我想路由器上的大型交换机并不会在速度上大幅领先于数据中心里服务器上的网卡。",-1)),l("p",null,[n[7]||(n[7]=t("这听起来有些糟糕，因为这意味着客户端更容易在中间层的连接中达到饱和，而这将导致互联网变慢（而且 ",-1)),a(i,{href:"https://apenwarr.ca/log/?m=201101#10"},{default:o(()=>[...n[6]||(n[6]=[t("缓冲膨胀",-1)])]),_:1}),n[8]||(n[8]=t(" 将带来更高的延迟）。",-1))]),n[43]||(n[43]=e('<p>所以为了提高互联网的性能且不让每个路由上的任务队列都达到饱和，客户端需要表现得更好并且在发送信息包的时候慢一点。</p><h3 id="以更慢的速率发送更多的信息包以达到更好的性能" tabindex="-1">以更慢的速率发送更多的信息包以达到更好的性能 <a class="header-anchor" href="#以更慢的速率发送更多的信息包以达到更好的性能" aria-label="Permalink to “以更慢的速率发送更多的信息包以达到更好的性能”">​</a></h3><p>下面的结论真的让我非常意外 —— 以更慢的速率发送信息包实际上可能会带来更好的性能（即便你是在整个传输过程中，这样做的唯一的人），下面是原因：</p><p>假设你打算发送 10MB 的数据，在你和你需要连接的客户端之间有一个中间层，并且它的传输速率_非常低_，例如 1MB/s。假设你可以辨别这个慢连接（或者更多的后续中间层）的速度，那么你有 2 个选择：</p><ol><li>一次性将这 10MB 的数据发送完，然后看看会发生什么。</li><li>减慢速率使得你能够以 1MB/s 的速率传给它。</li></ol><p>现在，无论你选择何种方式，你可能都会发生丢包的现象。所以这样看起来，你可能需要选择一次性发送所有的信息包这种方式，对吧？不！！实际上在你的数据流的中间环节丢包要比在你的数据流的最后丢包要好得多。假如在中间环节有些包被丢弃了，你需要送往的那个客户端可以察觉到这个事情，然后再告诉你，这样你就可以再次发送那些被丢弃的包，这样便没有多大的损失。但假如信息包在最末端被丢弃，那么客户端将完全没有办法知道你一次性发送了所有的信息包！所以基本上在某个时刻被丢弃的包没有让你收到 ACK 信号时，你需要启用超时机制，并且还得重新发送它们。而超时往往意味着需要花费很长时间！</p><p>所以为什么以更慢的速率发送数据会更好呢？假如你发送数据的速率快于连接中的瓶颈，这时所有的信息包将会在某个地方堆积成一个队列，这个队列将会被塞满，然后在你的数据流的最末端的信息包将会被丢弃。并且像我们刚才解释的那样，处于数据流最后面的信息包很有可能丢弃！所以相比于最初以合适的速率发送信息包，一次性发送它们将会触发超时机制，发送 10MB 的数据将会花费更长的时间。</p><p>我认为这非常酷，因为这个过程并不需要与互联网中的其他人合作 —— 即便其他的所有人都已非常快的速率传送他们的信息包，对你来说以合适的速率（中间层的瓶颈速率）传送你自己的信息包_仍然_更有优势。</p><h3 id="如何辨别发送数据的合适速率-bbr" tabindex="-1">如何辨别发送数据的合适速率：BBR！ <a class="header-anchor" href="#如何辨别发送数据的合适速率-bbr" aria-label="Permalink to “如何辨别发送数据的合适速率：BBR！”">​</a></h3>',9)),l("p",null,[n[11]||(n[11]=t("在上面我说过：“假设你可以辨别出位于你的终端和服务器之间慢连接的速率……”，那么如何做到呢？来自 Google（Jacobson 工作的地方）的某些专家已经提出了一个算法来估计瓶颈的速率！它叫做 BBR，由于本次的分享已经很长了，所以这里不做具体介绍，但你可以参考 ",-1)),a(i,{href:"https://queue.acm.org/detail.cfm?id=3022184"},{default:o(()=>[...n[9]||(n[9]=[t("BBR：基于拥塞的拥塞控制",-1)])]),_:1}),n[12]||(n[12]=t(" 和 ",-1)),a(i,{href:"https://blog.acolyer.org/2017/03/31/bbr-congestion-based-congestion-control/"},{default:o(()=>[...n[10]||(n[10]=[t("来自晨读论文的总结",-1)])]),_:1}),n[13]||(n[13]=t(" 这两处链接。",-1))]),l("p",null,[n[15]||(n[15]=t("（另外，",-1)),a(i,{href:"https://blog.acolyer.org/"},{default:o(()=>[...n[14]||(n[14]=[t("https://blog.acolyer.org",-1)])]),_:1}),n[16]||(n[16]=t(" 的每日“晨读论文”总结基本上是我学习和理解计算机科学论文的唯一方式，它有可能是整个互联网上最好的博客之一！）",-1))]),n[44]||(n[44]=e('<h3 id="网络代码被设计为运行得-尽可能快" tabindex="-1">网络代码被设计为运行得“尽可能快“ <a class="header-anchor" href="#网络代码被设计为运行得-尽可能快" aria-label="Permalink to “网络代码被设计为运行得“尽可能快“”">​</a></h3><p>所以，假设我们相信我们想以一个更慢的速率（例如以我们连接中的瓶颈速率）来传输数据。这很好，但网络软件并不是被设计为以一个可控速率来传输数据的！下面是我所理解的大多数网络软件怎么做的：</p><ol><li>现在有一个队列的信息包来临；</li><li>然后软件读取队列并尽可能快地发送信息包；</li><li>就这样，没有了。</li></ol><p>这个过程非常呆板 —— 假设我以一个非常快的速率发送信息包，而另一端的连接却非常慢。假如我所拥有的就是一个放置所有信息包的队列，当我实际要发送数据时，我并没有办法来控制这个发送过程，所以我便不能减慢这个队列传输的速率。</p><h3 id="一个更好的方式-给每个信息包一个-最早的出发时间" tabindex="-1">一个更好的方式：给每个信息包一个“最早的出发时间” <a class="header-anchor" href="#一个更好的方式-给每个信息包一个-最早的出发时间" aria-label="Permalink to “一个更好的方式：给每个信息包一个“最早的出发时间””">​</a></h3><p>BBR 协议将会修改 Linux 内核中 skb 的数据结构（这个数据结构被用来表达网络信息包），使得它有一个时间戳，这个时间戳代表着这个信息包应该被发送出去的最早时间。</p><p>对于 Linux 网络栈我不知道更多的详情了，但对于我来说，这个协议最有趣的地方是这个改动并不是一个非常大的改动！它只是添加了一个额外的时间戳而已。</p><h3 id="用时间轮盘替换队列" tabindex="-1">用时间轮盘替换队列！！！ <a class="header-anchor" href="#用时间轮盘替换队列" aria-label="Permalink to “用时间轮盘替换队列！！！”">​</a></h3><p>一旦我们将时间戳打到这些信息包上，我们怎样在合适的时间将它们发送出去呢？使用_时间轮盘_！</p>',9)),l("p",null,[n[18]||(n[18]=t("在前不久的“我们喜爱的论文”活动中（这是关于这次聚会描述的",-1)),a(i,{href:"https://www.meetup.com/Papers-We-Love-Montreal/events/235100825/"},{default:o(()=>[...n[17]||(n[17]=[t("某些好的链接",-1)])]),_:1}),n[19]||(n[19]=t("），有一个演讲谈论了关于时间轮盘的话题。时间轮盘是一类用来指导 Linux 的进程调度器决定何时运行进程的算法。",-1))]),n[45]||(n[45]=e('<p>Van Jacobson 说道：时间轮盘实际上比队列调度工作得更好 —— 它们都提供常数时间的操作，但因为某些缓存机制，时间轮盘的常数要更小一些。我真的没有太明白这里他说的关于性能的解释。</p><p>他说道：关于时间轮盘的一个关键点是你可以很轻松地用时间轮盘实现一个队列（但反之不能！）—— 假如每次你增加一个新的信息包，在最开始你说我想让它_现在_就被发送走，很显然这样你就可以得到一个队列了。而这个时间轮盘方法是向后兼容的，它使得你可以更容易地实现某些更加复杂的对流量非常敏感的算法，例如让你针对不同的信息包以不同的速率去发送它们。</p><h3 id="或许我们可以通过改善-linux-来修复互联网" tabindex="-1">或许我们可以通过改善 Linux 来修复互联网！ <a class="header-anchor" href="#或许我们可以通过改善-linux-来修复互联网" aria-label="Permalink to “或许我们可以通过改善 Linux 来修复互联网！”">​</a></h3><p>对于任何影响到整个互联网规模的问题，最为棘手的问题是当你要做出改善时，例如改变互联网协议的实现，你需要面对各种不同的设备。你要面对 Linux 的机器、BSD 的机器、Windows 的机器、各种各样的手机、瞻博或者思科的路由器以及数量繁多的其他设备！</p><p>但是在网络环境中 Linux 处于某种有趣的位置上！</p><ul><li>Android 手机运行着 Linux</li><li>大多数的消费级 WiFi 路由器运行着 Linux</li><li>无数的服务器运行着 Linux</li></ul><p>所以在任何给定的网络连接中，实际上很有可能在两端都有一台 Linux 机器（例如一个 Linux 服务器、或者一个 Linux 路由器、一台 Android 设备）。</p><p>所以重点是假如你想大幅改善互联网上的拥塞状况，只需要改变 Linux 网络栈就会大所不同（或许 iOS 网络栈也是类似的）。这也就是为什么在本次的 Linux 网络会议上有这样的一个演讲！</p><h3 id="互联网仍在改变-酷" tabindex="-1">互联网仍在改变！酷！ <a class="header-anchor" href="#互联网仍在改变-酷" aria-label="Permalink to “互联网仍在改变！酷！”">​</a></h3><p>通常我以为 TCP/IP 仍然是上世纪 80 年代的东西，所以当从这些专家口中听说这些我们正在设计的网路协议仍然有许多严重的问题时，真的是非常有趣，并且听说现在有不同的方式来设计它们。</p><p>当然也确实是这样 —— 网络硬件以及和速度相关的任何设备，以及人们使用网络来干的各种事情（例如观看 Netflix 的节目）等等，一直都在随着时间发生着改变，所以正因为这样，我们需要为 2018 年的互联网而不是为 1988 年的互联网设计我们不同的算法。</p><hr>',12)),l("p",null,[n[21]||(n[21]=t("via: ",-1)),a(i,{href:"https://jvns.ca/blog/2018/07/12/netdev-day-2--moving-away-from--as-fast-as-possible/"},{default:o(()=>[...n[20]||(n[20]=[t("https://jvns.ca/blog/2018/07/12/netdev-day-2--moving-away-from--as-fast-as-possible/",-1)])]),_:1})]),l("p",null,[n[25]||(n[25]=t("作者：",-1)),a(i,{href:"https://jvns.ca/about"},{default:o(()=>[...n[22]||(n[22]=[t("Julia Evans",-1)])]),_:1}),n[26]||(n[26]=t(" 译者：",-1)),a(i,{href:"https://github.com/FSSlc"},{default:o(()=>[...n[23]||(n[23]=[t("FSSlc",-1)])]),_:1}),n[27]||(n[27]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...n[24]||(n[24]=[t("wxy",-1)])]),_:1})]),l("p",null,[n[30]||(n[30]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[28]||(n[28]=[t("LCTT",-1)])]),_:1}),n[31]||(n[31]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:o(()=>[...n[29]||(n[29]=[t("Linux中国",-1)])]),_:1}),n[32]||(n[32]=t(" 荣誉推出",-1))])])}const P=s(u,[["render",f]]);export{C as __pageData,P as default};
